var n={en:`A client disputes a finished service. Moderators inspect photos and chats, and may order a partial refund while delaying provider payout.`,ua:`Клієнт оскаржує завершену послугу. Модератор перевіряє фото й листування та може вирішити частково повернути кошти, затримавши виплату.`};var s={en:[`Add dispute ownership, evidence storage and moderator permissions.`,`Model payout holds, partial refunds and appeals.`,`Audit every financial decision and notify both parties.`],ua:[`Додай власника суперечки, сховище доказів і права модератора.`,`Змоделюй блокування виплат, часткові повернення й апеляції.`,`Аудитуй фінансові рішення та повідомляй обидві сторони.`]};var i=[{en:`Only authorized case decisions release or reverse funds.`,ua:`Лише дозволені рішення розблоковують або повертають гроші.`},{en:`Every adjustment references an original payment and dispute.`,ua:`Кожне коригування пов’язане з первинною оплатою та суперечкою.`}];var d={scenario:n,tasks:s,checks:i};export{i as checks,d as default,n as scenario,s as tasks};